## 1. Analysis & Pre-Thinking

**Root cause of the crash**
The previous `CanvaEditor.vue` was written against a **non-existent API**. It called `createEditor({})` from `@woven-ecs/core`, but:
- `@woven-ecs/core` is **not installed** and does **not** export `createEditor`.
- The installed package is `@woven-canvas/vue@2.0.3`, whose current API has **no `createEditor`** and no `editor.on('change')` / `clearAllBlocks` / `createBlock` instance methods. Hence `createEditor is not defined`.

**Correct v2 API (verified against installed type declarations + upstream docs/example)**
- Render the whole editor with the `<WovenCanvas>` component — you never construct an `Editor` yourself.
- `@ready="(editor, store) => …"` gives you the `Editor` and `CanvasStore`.
- Create blocks with the **free function** `createBlock(ctx, { tag, position, size, rotateZ })` (it assigns `Synced` id + `rank` + `Block`).
- Attach extra components per built-in block tag:
  - `shape` → `Shape` (+ `Text` for a label)
  - `sticky-note` → `Color` (+ `Text`)
  - `text` → `Text`
- Read back with `Block.read(ctx, id)`, `Shape.read`, `Color.read`, `Text.read`, `Synced.read`.
- Detect edits with `editor.subscribe(defineQuery(q => q.with(Block)), (ctx) => …)`.
- All mutations must run inside `editor.nextTick(ctx => …)`.

**Strategic approach**
1. Rewrite `CanvaEditor.vue` to mount `<WovenCanvas>`, capture `editor`/`store` on `@ready`, and keep the same `v-model` (array of nodes) contract the `FileViewer` already expects — no `FileViewer` change required.
2. Keep the original simple `.canva` node schema (`{ id, type, x, y, width, height, fill, stroke, text }`) and map it to/from the ECS components (with hex ⇄ RGBA conversion).
3. Guard against feedback loops: ignore `subscribe` emissions while programmatically loading, and never mutate `fileContent` on save (the parent already does debounced disk writes).

**Dependencies & risks**
- ✅ `@woven-canvas/vue` and its peer `@woven-canvas/core` are present in `node_modules`, so `import … from '@woven-canvas/core'` resolves. (It's a peer dep, not declared in `package.json` — see note at the end.)
- `modelValue` is the root array; the parent wraps it as `{ "nodes": [...] }` on disk and unwraps on read — unchanged.

**Target files**
- `src/components/canva/CanvaEditor.vue` — **Modify** (full rewrite).

## 2. Minimum Changes Approach
Only `CanvaEditor.vue` changes. `FileViewer.vue` already imports it and passes `:modelValue` / `@update:modelValue`, so its contract is preserved.

## 3. File Changes

```vue src/components/canva/CanvaEditor.vue
<script setup>
import { WovenCanvas } from '@woven-canvas/vue'
import '@woven-canvas/vue/style.css'
import {
  Block,
  Shape,
  Color,
  Text,
  Synced,
  createBlock,
  addComponent,
  hasComponent,
  removeEntity,
  defineQuery
} from '@woven-canvas/core'
</script>

<template>
  <div class="w-full h-full relative overflow-hidden bg-base-300">
    <!-- Woven native Vue component renders the full infinite canvas -->
    <WovenCanvas
      class="w-full h-full"
      style="width: 100%; height: 100%"
      :background="{ kind: 'dots' }"
      @ready="onReady"
    />
    <!-- Engine initializing placeholder -->
    <div
      class="absolute inset-0 flex items-center justify-center opacity-60 text-sm pointer-events-none"
      v-if="!ready"
    >
      <span class="loading loading-spinner loading-md mr-2"></span>
      Initializing canvas…
    </div>
  </div>
</template>

<script>
export default {
  name: 'CanvaEditor',
  props: {
    // Continuous layout JSON definition (array of canvas nodes)
    modelValue: {
      type: Array,
      default: () => []
    }
  },
  emits: ['update:modelValue'],
  data() {
    return {
      editor: null,
      store: null,
      ready: false,
      isUpdatingFromProp: false,
      unsubscribeChange: null,
      blockQuery: null
    }
  },
  watch: {
    // Deep watch for when the definition is replaced externally (AI / reload)
    modelValue: {
      deep: true,
      handler(nodes) {
        if (!this.ready || this.isUpdatingFromProp) return
        this.loadJsonToCanvas(nodes)
      }
    }
  },
  beforeUnmount() {
    if (this.unsubscribeChange) {
      this.unsubscribeChange()
      this.unsubscribeChange = null
    }
  },
  methods: {
    // Called by <WovenCanvas @ready> with the editor and store instances
    onReady(editor, store) {
      this.editor = editor
      this.store = store
      this.blockQuery = defineQuery((q) => q.with(Block))
      // Push visual changes made on canvas back through v-model
      this.unsubscribeChange = editor.subscribe(this.blockQuery, (ctx) => {
        if (this.isUpdatingFromProp) return
        this.$emit('update:modelValue', this.exportCanvasToJson(ctx))
      })
      this.ready = true
      // Load the starting definition stored in modelValue
      this.loadJsonToCanvas(this.modelValue)
    },
    // Wipe the workspace and load the node list as Woven blocks
    loadJsonToCanvas(nodes) {
      if (!this.editor || !this.blockQuery) return
      const list = Array.isArray(nodes) ? nodes : []
      // Block change emissions while resetting the canvas
      this.isUpdatingFromProp = true
      this.editor.nextTick((ctx) => {
        Array.from(this.blockQuery.current(ctx)).forEach((entityId) => {
          removeEntity(ctx, entityId)
        })
        list.forEach((node) => this.createNodeBlock(ctx, node))
        // Re-enable change events once this programmatic update has settled
        setTimeout(() => {
          this.isUpdatingFromProp = false
        }, 0)
      })
    },
    // Map a plain node definition to a Woven block entity
    createNodeBlock(ctx, node) {
      const tag = node.type || node.tag || 'shape'
      const entityId = createBlock(ctx, {
        tag,
        position: [Number(node.x) || 0, Number(node.y) || 0],
        size: [Number(node.width) || 160, Number(node.height) || 120],
        rotateZ: Number(node.rotateZ) || 0
      })
      // Preserve the stable id when possible (informational)
      if (node.id) {
        try {
          Synced.copy(ctx, entityId, { id: node.id })
        } catch (ex) {
          console.warn('Could not restore block id', ex)
        }
      }
      if (tag === 'shape') {
        const fill = hexToRgba(node.fill, [255, 255, 255, 255])
        const stroke = hexToRgba(node.stroke, [203, 213, 225, 255])
        addComponent(ctx, entityId, Shape, {
          kind: node.kind || 'rectangle',
          strokeKind: 'solid',
          strokeWidth: 4,
          strokeRed: stroke[0],
          strokeGreen: stroke[1],
          strokeBlue: stroke[2],
          strokeAlpha: stroke[3],
          fillRed: fill[0],
          fillGreen: fill[1],
          fillBlue: fill[2],
          fillAlpha: fill[3]
        }, true)
      } else if (tag === 'sticky-note') {
        const fill = hexToRgba(node.fill, [255, 242, 117, 255])
        addComponent(ctx, entityId, Color, {
          red: fill[0],
          green: fill[1],
          blue: fill[2],
          alpha: fill[3]
        }, true)
      }
      if (node.text) {
        addComponent(ctx, entityId, Text, { content: String(node.text) }, true)
      }
    },
    // Gather all block properties back into a plain node array
    exportCanvasToJson(ctx) {
      const activeContext = ctx || (this.editor && this.editor._getContext())
      if (!activeContext || !this.blockQuery) return []
      return Array.from(this.blockQuery.current(activeContext))
        .map((entityId) => this.blockToNode(activeContext, entityId))
    },
    // Read a single block entity back into a plain node definition
    blockToNode(ctx, entityId) {
      const block = Block.read(ctx, entityId)
      const node = {
        id: this.readSyncedId(ctx, entityId),
        type: block.tag,
        x: block.position[0],
        y: block.position[1],
        width: block.size[0],
        height: block.size[1]
      }
      if (block.rotateZ) {
        node.rotateZ = block.rotateZ
      }
      if (hasComponent(ctx, entityId, Shape)) {
        const shape = Shape.read(ctx, entityId)
        node.kind = shape.kind
        node.stroke = rgbaToHex(shape.strokeRed, shape.strokeGreen, shape.strokeBlue)
        node.fill = rgbaToHex(shape.fillRed, shape.fillGreen, shape.fillBlue)
      }
      if (hasComponent(ctx, entityId, Color)) {
        const color = Color.read(ctx, entityId)
        node.fill = rgbaToHex(color.red, color.green, color.blue)
      }
      if (hasComponent(ctx, entityId, Text)) {
        node.text = Text.read(ctx, entityId).content
      }
      return node
    },
    readSyncedId(ctx, entityId) {
      try {
        if (hasComponent(ctx, entityId, Synced)) {
          return Synced.read(ctx, entityId).id
        }
      } catch (ex) {
        console.warn('Could not read synced id', ex)
      }
      return null
    }
  }
}

// Parse "#rgb" / "#rrggbb" into an [r, g, b, a] tuple
function hexToRgba(hex, fallback) {
  if (!hex || typeof hex !== 'string') return fallback
  let value = hex.replace('#', '').trim()
  if (value.length === 3) {
    value = value.split('').map((c) => c + c).join('')
  }
  if (value.length !== 6) return fallback
  const num = parseInt(value, 16)
  if (Number.isNaN(num)) return fallback
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255, 255]
}

// Convert color channels back into a "#rrggbb" string
function rgbaToHex(r, g, b) {
  const channel = (v) => Math.max(0, Math.min(255, Math.round(v || 0))).toString(16).padStart(2, '0')
  return `#${channel(r)}${channel(g)}${channel(b)}`
}
</script>
