<script setup>
import { WovenCanvas } from "@woven-canvas/vue"
import "@woven-canvas/vue/style.css"
</script>

<template>
  <div class="w-full h-full relative overflow-hidden bg-base-300">
    <!-- Engine initializing placeholder -->
    <div class="w-full h-full flex items-center justify-center opacity-50 text-sm" v-if="!editor">
      <span class="loading loading-spinner loading-md mr-2"></span>
      Initializing canvas...
    </div>
    <!-- Woven native Vue component -->
    <WovenCanvas v-else :editor="editor" />
  </div>
</template>

<script>

export default {
  name: 'CanvaEditor',
  props: {
    // Continuous layout JSON definition (array of canvas nodes)
    modelValue: {
      type: Array,
      default: () => []
    }
  },
  emits: ['update:modelValue'],
  data() {
    return {
      editor: null,
      isUpdatingFromProp: false
    }
  },
  mounted() {
    // 1. Core initialization of the Woven engine
    this.editor = createEditor({})
    // 2. Load the starting definition stored in modelValue
    if (this.modelValue?.length) {
      this.loadJsonToCanvas(this.modelValue)
    }
    // 3. Push visual changes made on canvas back through v-model
    this.editor.on('change', this.onCanvasChange)
  },
  beforeUnmount() {
    if (this.editor?.off) {
      this.editor.off('change', this.onCanvasChange)
    }
  },
  watch: {
    // Deep watch for when the definition is replaced externally (AI/DB)
    modelValue: {
      deep: true,
      handler(nodes) {
        if (!this.editor || this.isUpdatingFromProp) return
        this.loadJsonToCanvas(nodes)
      }
    }
  },
  methods: {
    // Wipe the workspace and load the JSON node tree as Woven shapes
    loadJsonToCanvas(nodes) {
      if (!this.editor) return
      this.editor.clearAllBlocks()
      ;(nodes || []).forEach(node => {
        this.editor.createBlock({
          id: node.id,
          type: node.type || 'shape',
          x: node.x,
          y: node.y,
          width: node.width,
          height: node.height,
          style: {
            fill: node.fill || '#ffffff',
            stroke: node.stroke || '#cbd5e1',
            text: node.text || ''
          }
        })
      })
    },
    // Gather all layout properties back into a plain JSON array
    exportCanvasToJson() {
      if (!this.editor) return []
      const blocks = this.editor.getAllBlocks()
      return blocks.map(block => ({
        id: block.id,
        type: block.type,
        x: block.x,
        y: block.y,
        width: block.width,
        height: block.height,
        fill: block.style?.fill,
        stroke: block.style?.stroke,
        text: block.style?.text
      }))
    },
    // Emit visual changes while avoiding an update feedback loop
    onCanvasChange() {
      if (this.isUpdatingFromProp) return
      const json = this.exportCanvasToJson()
      this.isUpdatingFromProp = true
      this.$emit('update:modelValue', json)
      this.$nextTick(() => {
        this.isUpdatingFromProp = false
      })
    }
  }
}
</script>
