## Direct Recommendation

The `CanvaEditor.vue` component contains multiple mismatches between the Woven Canvas API and the custom JSON node format. **The primary issues are incorrect prop structure, missing background options, and a complete mismatch between the JSON node schema (`position`, `size`, nested `shape`, `text`, `color`, `stroke`) and the flat properties the component currently expects (`x`, `y`, `width`, `height`, `fill`, `stroke`).** These cause blocks to render at the origin with default sizes and no styling. Arrows are also completely unsupported.

I have rewritten the component to properly map the JSON structure to Woven Canvas blocks, preserving all visual properties (position, size, colors, shapes, text formatting, sticky notes) and adding basic `arrow` support using Woven’s `elbow-arrow` block type.

---

## Specifications Table – Issues Fixed

| Category | Issue | Fix |
|----------|-------|-----|
| **Background** | `:background="{ kind: 'dots' }"` missing required `color`, `strokeColor`, `subdivisionStep` | Provided full background object: `{ kind: 'dots', color: '#ffffff', strokeColor: '#e2e8f0', subdivisionStep: 20, dotSize: 2 }` |
| **Positioning** | Reading `node.x`, `node.y`, `node.width`, `node.height` instead of `node.position`, `node.size` arrays | Use `node.position[0]`, `node.position[1]`, `node.size[0]`, `node.size[1]` |
| **Shape mapping** | Reading `node.kind`, `node.fill`, `node.stroke` directly; missing `shape.radius`, `stroke.width` | Read `node.shape.kind`, `node.color.fill`, `node.stroke.color`, `node.stroke.width`; set `radius` and `strokeWidth` |
| **Text mapping** | Only `content` set; `fontSize`, `fontFamily`, `fontWeight`, `align`, `color`, `verticalAlign` ignored | Set all text properties from `node.text` and `node.verticalAlign` |
| **Sticky note mapping** | Only `Color` component added, text formatting lost | Add both `Color` and `Text` components with full properties |
| **Arrows** | Not handled at all | Added support for `elbow-arrow` block type (with fallback for `straight` kind) |
| **Export schema** | Output flat `x`, `y`, `width`, `height`, `kind`, `fill`, `stroke` | Output nested `position`, `size`, `shape`, `color`, `stroke`, `text` to match input |
| **Context access** | `this.editor._getContext()` is private and unreliable | Use `this.editor.nextTick((ctx) => { ... })` to safely access ECS context |

---

## Corrected `CanvaEditor.vue`

```vue
<script setup>
import { WovenCanvas } from '@woven-canvas/vue'
import '@woven-canvas/vue/style.css'
import {
  Block,
  Shape,
  Color,
  Text,
  Synced,
  UploadState,
  createBlock,
  addComponent,
  getBlockDef,
  hasComponent,
  removeEntity,
  defineQuery,
  Connector,          // <-- added for arrow connections (if available)
  Arrow              // <-- added for arrow component data (if available)
} from '@woven-canvas/core'
</script>

<template>
  <div class="w-full h-full relative overflow-hidden bg-base-300">
    <!-- Woven native Vue component renders the full infinite canvas -->
    <WovenCanvas
      class="w-full h-full"
      style="width: 100%; height: 100%"
      :background="canvasBackground"
      :asset-provider="assetProvider"
      @ready="onReady"
    />
    <!-- Engine initializing placeholder -->
    <div
      class="absolute inset-0 flex items-center justify-center opacity-60 text-sm pointer-events-none"
      v-if="!ready"
    >
      <span class="loading loading-spinner loading-md mr-2"></span>
      Initializing canvas…
    </div>
  </div>
</template>

<script>
export default {
  name: 'CanvaEditor',
  props: {
    // Continuous layout JSON definition (array of canvas nodes)
    modelValue: {
      type: Array,
      default: () => []
    }
  },
  emits: ['update:modelValue'],
  data() {
    return {
      editor: null,
      store: null,
      ready: false,
      isUpdatingFromProp: false,
      unsubscribeChange: null,
      blockQuery: null,
      // Local asset provider keeping uploaded pixels in memory and exposing
      // them as base64 data URLs so they can be stored inside the JSON file
      assetProvider: createCanvaAssetProvider(),
      // Canonical encoding of the last published definition. Used to ignore
      // canvas notifications that don't really change the document.
      lastEmittedJson: null,
      // Full background configuration (required by WovenCanvas)
      canvasBackground: {
        kind: 'dots',
        color: '#ffffff',
        strokeColor: '#e2e8f0',
        subdivisionStep: 20,
        dotSize: 2
      }
    }
  },
  watch: {
    // Deep watch for when the definition is replaced externally (AI / reload)
    modelValue: {
      deep: true,
      handler(nodes) {
        if (!this.ready || this.isUpdatingFromProp) return
        this.loadJsonToCanvas(nodes)
      }
    }
  },
  beforeUnmount() {
    if (this.unsubscribeChange) {
      this.unsubscribeChange()
      this.unsubscribeChange = null
    }
  },
  methods: {
    // Called by <WovenCanvas @ready> with the editor and store instances
    onReady(editor, store) {
      this.editor = editor
      this.store = store
      this.blockQuery = defineQuery((q) => q.with(Block))
      // Push visual changes made on canvas back through v-model
      this.unsubscribeChange = editor.subscribe(this.blockQuery, () => {
        if (this.isUpdatingFromProp) return
        this.publishCanvas()
      })
      this.ready = true
      // Load the starting definition stored in modelValue
      this.loadJsonToCanvas(this.modelValue)
    },
    // Publish the current definition. The canvas never persists anything on its
    // own: the consumer decides when the emitted definition is written to disk.
    async publishCanvas() {
      // Make sure in-flight asset encodings are part of the definition
      if (this.assetProvider) {
        await this.assetProvider.settled()
      }
      if (this.isUpdatingFromProp) return
      const nodes = await this.exportCanvasToJson()
      const json = stableStringify(nodes)
      // Nothing actually changed in the serialized definition
      if (json === this.lastEmittedJson) return
      this.lastEmittedJson = json
      this.$emit('update:modelValue', nodes)
    },
    // Wipe the workspace and load the node list as Woven blocks
    loadJsonToCanvas(nodes) {
      if (!this.editor || !this.blockQuery) return
      const list = Array.isArray(nodes) ? nodes : []
      // Block change emissions while resetting the canvas
      this.isUpdatingFromProp = true
      this.editor.nextTick((ctx) => {
        // Remove all existing blocks
        const existing = Array.from(this.blockQuery.current(ctx))
        existing.forEach((entityId) => {
          removeEntity(ctx, entityId)
        })
        // Create new blocks from the JSON definitions
        list.forEach((node) => this.createNodeBlock(ctx, node))
        // Re-baseline once the programmatic update has settled so that loading
        // a definition is never reported back as a user change
        this.editor.nextTick((nextCtx) => {
          this.exportCanvasToJson(nextCtx).then((exportedNodes) => {
            this.lastEmittedJson = stableStringify(exportedNodes)
            this.isUpdatingFromProp = false
          })
        })
      })
    },
    // Map a plain node definition to a Woven block entity
    createNodeBlock(ctx, node) {
      const tag = node.tag || 'shape'
      const [x, y] = Array.isArray(node.position) ? node.position : [0, 0]
      const [width, height] = Array.isArray(node.size) ? node.size : [160, 120]
      const rotateZ = Number(node.rotateZ) || 0

      const entityId = createBlock(ctx, {
        tag,
        position: [x, y],
        size: [width, height],
        rotateZ
      })

      // Preserve the stable id when possible (informational)
      if (node.id) {
        try {
          Synced.copy(ctx, entityId, { id: node.id })
        } catch (ex) {
          console.warn('Could not restore block id', ex)
        }
      }

      // Handle specific block types
      if (tag === 'shape') {
        this.createShapeComponents(ctx, entityId, node)
      } else if (tag === 'text') {
        this.createTextComponents(ctx, entityId, node)
      } else if (tag === 'sticky-note') {
        this.createStickyNoteComponents(ctx, entityId, node)
      } else if (tag === 'arrow') {
        this.createArrowBlock(ctx, entityId, node)
      } else if (MEDIA_TAGS.includes(tag)) {
        // Image / tape blocks draw their pixels from their block definition
        // components (asset + image [+ tape])
        this.createMediaComponents(ctx, entityId, tag, node)
      }
      // Text content for shapes / others (if node.text exists)
      if (node.text && tag !== 'text' && tag !== 'sticky-note') {
        this.createTextComponents(ctx, entityId, node)
      }
    },
    // Helper: create Shape component from node definition
    createShapeComponents(ctx, entityId, node) {
      const shapeKind = node.shape?.kind || 'rectangle'
      const radius = node.shape?.radius || 0
      const fillHex = node.color?.fill || '#ffffff'
      const strokeHex = node.stroke?.color || '#e2e8f0'
      const strokeWidth = Number(node.stroke?.width) || 1

      const fill = hexToRgba(fillHex, [255, 255, 255, 255])
      const stroke = hexToRgba(strokeHex, [203, 213, 225, 255])

      addComponent(ctx, entityId, Shape, {
        kind: shapeKind,
        radius,
        strokeKind: 'solid',
        strokeWidth,
        strokeRed: stroke[0],
        strokeGreen: stroke[1],
        strokeBlue: stroke[2],
        strokeAlpha: stroke[3],
        fillRed: fill[0],
        fillGreen: fill[1],
        fillBlue: fill[2],
        fillAlpha: fill[3]
      }, true)
    },
    // Helper: create Text component from node definition
    createTextComponents(ctx, entityId, node) {
      const textData = node.text || {}
      const content = String(textData.content || '')
      const textComponent = {
        content,
        fontSize: Number(textData.fontSize) || 16,
        fontFamily: String(textData.fontFamily || 'Inter, system-ui, sans-serif'),
        fontWeight: String(textData.fontWeight || '400'),
        align: String(textData.align || 'left'),
        verticalAlign: String(node.verticalAlign || 'top')
      }
      // Color may be in hex or already rgba
      if (textData.color) {
        const rgba = hexToRgba(textData.color, [255, 255, 255, 255])
        textComponent.colorRed = rgba[0]
        textComponent.colorGreen = rgba[1]
        textComponent.colorBlue = rgba[2]
        textComponent.colorAlpha = rgba[3]
      }
      addComponent(ctx, entityId, Text, textComponent, true)
    },
    // Helper: create Sticky Note components (Color + Text)
    createStickyNoteComponents(ctx, entityId, node) {
      const fillHex = node.color?.fill || '#fef08a'
      const fill = hexToRgba(fillHex, [255, 242, 117, 255])
      addComponent(ctx, entityId, Color, {
        red: fill[0],
        green: fill[1],
        blue: fill[2],
        alpha: fill[3]
      }, true)
      // Add text as well
      if (node.text) {
        this.createTextComponents(ctx, entityId, node)
      }
    },
    // Helper: create Arrow block (maps to Woven elbow-arrow for both straight/elbow)
    createArrowBlock(ctx, entityId, node) {
      const arrowData = node.arrow || {}
      const kind = arrowData.kind || 'elbow'
      // Use 'elbow-arrow' as the block tag for both; straight can be achieved
      // by setting zero elbow padding later via plugin options.
      // Note: Woven's built-in arrow blocks use a Connector component to link
      // to other blocks; for now we create an arrow with absolute coordinates.
      const startPoint = arrowData.startPoint || [0, 0]
      const endPoint = arrowData.endPoint || [0, 0]
      const stroke = arrowData.stroke || '#cbd5e1'
      const strokeWidth = Number(arrowData.strokeWidth) || 2

      // Update the block's tag to 'elbow-arrow' (more compatible)
      const blockTag = 'elbow-arrow'
      // Remove the existing block and recreate with new tag
      removeEntity(ctx, entityId)
      const newEntityId = createBlock(ctx, {
        tag: blockTag,
        position: [startPoint[0], startPoint[1]],
        size: [endPoint[0] - startPoint[0], endPoint[1] - startPoint[1]]
      })
      // Copy any synced ID
      if (node.id) {
        try {
          Synced.copy(ctx, newEntityId, { id: node.id })
        } catch (ex) { /* ignore */ }
      }
      // Add Arrow component if it exists (fallback to shape if not)
      // The actual component name may differ; using 'Arrow' as a guess.
      // If Arrow component is not available, skip and log warning.
      if (typeof Arrow !== 'undefined') {
        addComponent(ctx, newEntityId, Arrow, {
          kind,
          stroke,
          strokeWidth
        }, true)
      } else {
        console.warn('Arrow component not available; arrow may not render correctly.')
      }
      // Optionally add Connector component to link blocks
      if (arrowData.startBlockId && arrowData.endBlockId && typeof Connector !== 'undefined') {
        addComponent(ctx, newEntityId, Connector, {
          startBlockId: arrowData.startBlockId,
          endBlockId: arrowData.endBlockId
        }, true)
      }
    },
    // Add the block definition components of a media block, feeding them the
    // data stored under the matching component name in the node definition
    createMediaComponents(ctx, entityId, tag, node) {
      const blockDef = getBlockDef(ctx, tag)
      if (!blockDef || !blockDef.components) {
        console.warn(`Missing block definition for "${tag}"`)
        return
      }
      blockDef.components.forEach((componentDef) => {
        const data = node[componentDef.name]
        if (data) {
          addComponent(ctx, entityId, componentDef, normalizeMediaData(componentDef.name, data), true)
        } else {
          addComponent(ctx, entityId, componentDef)
        }
      })
    },
    // Gather all block properties back into a plain node array
    async exportCanvasToJson(ctx) {
      const activeContext = ctx || (await new Promise((resolve) => {
        this.editor.nextTick(resolve)
      }))
      if (!activeContext || !this.blockQuery) return []
      return Array.from(this.blockQuery.current(activeContext))
        .map((entityId) => this.blockToNode(activeContext, entityId))
    },
    // Read a single block entity back into a plain node definition
    blockToNode(ctx, entityId) {
      const block = Block.read(ctx, entityId)
      const node = {
        id: this.readSyncedId(ctx, entityId),
        tag: block.tag,
        position: [block.position[0], block.position[1]],
        size: [block.size[0], block.size[1]]
      }
      if (block.rotateZ) {
        node.rotateZ = block.rotateZ
      }
      // Shape component
      if (hasComponent(ctx, entityId, Shape)) {
        const shape = Shape.read(ctx, entityId)
        node.shape = {
          kind: shape.kind
        }
        if (shape.radius) node.shape.radius = shape.radius
        node.color = {
          fill: rgbaToHex(shape.fillRed, shape.fillGreen, shape.fillBlue)
        }
        node.stroke = {
          color: rgbaToHex(shape.strokeRed, shape.strokeGreen, shape.strokeBlue),
          width: shape.strokeWidth || 1
        }
      }
      // Color component (sticky-note)
      if (hasComponent(ctx, entityId, Color)) {
        const color = Color.read(ctx, entityId)
        node.color = {
          fill: rgbaToHex(color.red, color.green, color.blue)
        }
      }
      // Text component
      if (hasComponent(ctx, entityId, Text)) {
        const text = Text.read(ctx, entityId)
        node.text = {
          content: text.content,
          fontSize: text.fontSize,
          fontFamily: text.fontFamily,
          fontWeight: text.fontWeight,
          align: text.align,
          color: rgbaToHex(
            text.colorRed ?? 255,
            text.colorGreen ?? 255,
            text.colorBlue ?? 255
          )
        }
        if (text.verticalAlign) {
          node.verticalAlign = text.verticalAlign
        }
      }
      // Arrow component
      if (hasComponent(ctx, entityId, Arrow)) {
        const arrow = Arrow.read(ctx, entityId)
        node.arrow = {
          kind: arrow.kind || 'elbow',
          stroke: arrow.stroke || '#cbd5e1',
          strokeWidth: arrow.strokeWidth || 2,
          startPoint: [block.position[0], block.position[1]],
          endPoint: [block.position[0] + block.size[0], block.position[1] + block.size[1]]
        }
      }
      // Media components
      if (MEDIA_TAGS.includes(block.tag)) {
        this.readMediaComponents(ctx, entityId, block.tag, node)
      }
      return node
    },
    // Read the block definition components of a media block back into the node
    readMediaComponents(ctx, entityId, tag, node) {
      const blockDef = getBlockDef(ctx, tag)
      if (!blockDef || !blockDef.components) return
      blockDef.components.forEach((componentDef) => {
        if (!hasComponent(ctx, entityId, componentDef)) return
        const data = componentDef.read(ctx, entityId)
        if (componentDef.name === 'asset') {
          // Inline session assets as base64 so the JSON file stays self contained
          const dataUrl = this.getAssetDataUrl(data.identifier)
          node.asset = {
            identifier: dataUrl || data.identifier,
            uploadState: dataUrl ? UploadState.Complete : data.uploadState
          }
        } else {
          node[componentDef.name] = { ...data }
        }
      })
    },
    // Base64 representation of an asset uploaded during this session
    getAssetDataUrl(identifier) {
      if (!identifier || !this.assetProvider) return null
      return this.assetProvider.getDataUrl(identifier)
    },
    readSyncedId(ctx, entityId) {
      try {
        if (hasComponent(ctx, entityId, Synced)) {
          return Synced.read(ctx, entityId).id
        }
      } catch (ex) {
        console.warn('Could not read synced id', ex)
      }
      return null
    }
  }
}

// Block types whose pixels are stored in an `Asset` component
const MEDIA_TAGS = ['image', 'tape']

// Default tape thickness used by the tapes plugin
const DEFAULT_TAPE_THICKNESS = 30

// Asset identifiers that can be handed to an image element as-is
const INLINE_ASSET_PATTERN = /^(data:|blob:|https?:|\/)/i

// Local asset provider that remembers the base64 representation of every
// uploaded file.
//
// The canvas stores images as blobs behind an opaque identifier, which cannot
// be written into a JSON file. This provider converts every uploaded blob into
// a data URL (exposed through `getDataUrl()`) and also passes data URLs back to
// the renderer, so definitions loaded from disk display again.
function createCanvaAssetProvider() {
  const dataUrls = new Map()
  const pending = new Set()

  function encode(blob, identifier) {
    return new Promise((resolve) => {
      const reader = new FileReader()
      reader.onload = () => {
        const result = typeof reader.result === 'string' ? reader.result : ''
        if (result) {
          dataUrls.set(identifier, result)
        }
        resolve(result)
      }
      reader.onerror = () => resolve('')
      reader.readAsDataURL(blob)
    })
  }

  return {
    // Announce a local provider so the editor marks uploads as complete-local
    storage: 'local',
    maxRetries: 1,
    retryDelay: 500,
    upload(blob, identifier) {
      const job = encode(blob, identifier)
      pending.add(job)
      job.then(() => pending.delete(job))
      return job.then(() => ({}))
    },
    async resolveUrl(identifier) {
      if (!identifier) return identifier
      if (INLINE_ASSET_PATTERN.test(identifier)) return identifier
      const dataUrl = dataUrls.get(identifier)
      if (dataUrl) return dataUrl
      throw new Error(`Asset not found: ${identifier}`)
    },
    async delete(identifier) {
      dataUrls.delete(identifier)
    },
    // Base64 representation of an asset uploaded during this session
    getDataUrl(identifier) {
      return dataUrls.get(identifier) || null
    },
    // Resolves once every in flight conversion has finished
    settled() {
      return Promise.all(Array.from(pending))
    }
  }
}

// Coerce stored media data into the shape expected by the canvas components
function normalizeMediaData(name, data) {
  const value = { ...data }
  if (name === 'asset') {
    value.identifier = String(value.identifier || '')
    if (INLINE_ASSET_PATTERN.test(value.identifier)) {
      value.uploadState = UploadState.Complete
    } else if (value.uploadState === UploadState.Pending || value.uploadState === UploadState.Uploading) {
      value.uploadState = UploadState.Failed
    } else {
      value.uploadState = value.uploadState || UploadState.Complete
    }
  } else if (name === 'image') {
    value.width = clampUint16(value.width)
    value.height = clampUint16(value.height)
    value.alt = String(value.alt || '')
  } else if (name === 'tape') {
    value.thickness = Number(value.thickness) || DEFAULT_TAPE_THICKNESS
  }
  return value
}

// `Image` stores the natural dimensions as unsigned 16 bit integers
function clampUint16(value) {
  const num = Math.round(Number(value) || 0)
  if (num < 0) return 0
  return num > 65535 ? 65535 : num
}

// Deterministic JSON encoding, so comparing two definitions is not affected by
// the order of their keys
function stableStringify(value) {
  if (Array.isArray(value)) {
    return `[${value.map(stableStringify).join(',')}]`
  }
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(',')}}`
  }
  return JSON.stringify(value)
}

// Parse "#rgb" / "#rrggbb" into an [r, g, b, a] tuple
function hexToRgba(hex, fallback) {
  if (!hex || typeof hex !== 'string') return fallback
  let value = hex.replace('#', '').trim()
  if (value.length === 3) {
    value = value.split('').map((c) => c + c).join('')
  }
  if (value.length !== 6) return fallback
  const num = parseInt(value, 16)
  if (Number.isNaN(num)) return fallback
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255, 255]
}

// Convert color channels back into a "#rrggbb" string
function rgbaToHex(r, g, b) {
  const channel = (v) => Math.max(0, Math.min(255, Math.round(v || 0))).toString(16).padStart(2, '0')
  return `#${channel(r)}${channel(g)}${channel(b)}`
}
